INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 341, 4, 'cut 으로 상태 코드 칸 뽑기', '접속 로그 한 줄은 아래와 같고, 칸은 공백으로 나뉩니다. `cut -d'' '' -f9 access.log` 와 **같은 결과**를 내는 awk 명령을 고르세요.

```
192.0.2.10 - - [10/Nov/2026:09:00:00 +0000] "GET /index.html HTTP/1.1" 200 5120
```', '공백으로 나눠 앞에서부터 번호를 세어 보세요. 1번은 IP, 2번과 3번은 `-`, 4번은 `[날짜`, 5번은 `+0000]` 입니다. 그 뒤로 이어서 세면 됩니다. `cut -d` 는 구분 문자, `-f` 는 칸 번호입니다.', NULL, NULL, '[]', 'choice', '["`awk ''{print $8}'' access.log` — 공백으로 나눈 8번째 칸(HTTP 버전)이다", "`awk ''{print $10}'' access.log` — 공백으로 나눈 10번째 칸(바이트 수)이다", "`awk ''{print $NF}'' access.log` — 공백으로 나눈 마지막 칸(바이트 수)이다", "`awk ''{print $9}'' access.log` — 공백으로 나눈 9번째 칸(상태 코드)이다"]', 3, '`cut -d'' '' -f9` 는 공백으로 자른 9번째 칸을 뽑고, awk 의 `$9` 도 똑같이 공백으로 나눈 9번째 칸입니다. 이 로그에서는 1번 IP, 2·3번 `-`, 4번 `[날짜`, 5번 `+0000]`, 6번 `"GET`, 7번 경로, 8번 `HTTP/1.1"`, 9번 상태 코드, 10번 바이트 수입니다. 그래서 `$8` 은 HTTP 버전, `$10` 과 `$NF` 는 바이트 수를 뽑습니다. 단, 칸 사이가 공백 하나씩일 때만 `cut` 과 awk 가 같습니다. 공백이 여러 개 이어진 줄에서는 `cut` 이 빈 칸을 세지만 awk 는 합쳐서 한 칸으로 봅니다.', NULL, NULL, NULL, '[{"title": "GNU coreutils 매뉴얼: sort 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/sort-invocation.html"}, {"title": "GNU coreutils 매뉴얼: uniq 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/uniq-invocation.html"}, {"title": "GNU coreutils 매뉴얼: cut 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cut-invocation.html"}, {"title": "GNU awk 사용자 안내서: 필드 읽기", "url": "https://www.gnu.org/software/gawk/manual/html_node/Fields.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 341 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 341, 5, '같은 IP 를 이웃하게 모으기 (uniq 앞의 한 단계)', 'IP 별로 요청이 몇 번인지 세려고 합니다. `uniq -c` 는 **바로 이웃한** 같은 줄만 묶어서 셉니다. 중간 단계가 흩어진 줄을 이웃하게 모아 주도록 빈칸을 채우세요.', '`uniq` 는 줄이 흩어져 있으면 같은 값이라도 따로 셉니다. 같은 값이 붙어 있도록 줄을 **정렬**해 주는 명령이 필요합니다.', NULL, NULL, '[]', 'fill', '["sort", "head", "tac", "cat"]', NULL, '`sort` 가 같은 IP 를 한 곳에 모아 주므로 그 뒤의 `uniq -c` 가 IP 마다 정확히 한 줄씩 세어 줍니다. `head` 는 앞쪽 몇 줄만 남기고, `tac` 은 줄 순서만 뒤집으며, `cat` 은 그대로 통과시키므로 셋 다 같은 IP 를 이웃하게 모으지 못해 같은 IP 가 여러 줄로 나뉘어 셉니다.', '[0]', 'awk ''{print $1}'' /tmp/lab/access.log | {0} | uniq -c', NULL, '[{"title": "GNU coreutils 매뉴얼: sort 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/sort-invocation.html"}, {"title": "GNU coreutils 매뉴얼: uniq 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/uniq-invocation.html"}, {"title": "GNU coreutils 매뉴얼: cut 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cut-invocation.html"}, {"title": "GNU awk 사용자 안내서: 필드 읽기", "url": "https://www.gnu.org/software/gawk/manual/html_node/Fields.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 341 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 341, 6, 'IP 별 요청 횟수 세기 (sort | uniq -c)', '`access.log` 에서 **IP 마다 요청이 몇 번**인지 세어 **`/tmp/lab/per_ip.txt`** 에 저장하세요. 한 줄에 `횟수 IP` 모양이고, IP 는 한 번씩만 나와야 합니다. IP 는 awk 로 뽑습니다.', '`awk` 로 IP 칸만 뽑고, 같은 값을 모으려고 `sort`, 세려고 `uniq -c` 를 차례로 파이프(`|`)로 잇습니다. 전체를 `>` 로 파일에 보냅니다.', 'awk ''{print $1}'' /tmp/lab/access.log | sort | uniq -c > /tmp/lab/per_ip.txt
cat /tmp/lab/per_ip.txt

