INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 341, 7, '가장 많이 요청한 IP 3개 (sort -rn | head -3)', '5번의 결과를 이어서, **요청이 가장 많은 IP 3개**를 `횟수 IP` 모양으로 **많은 순**으로 **`/tmp/lab/top3.txt`** 에 저장하세요. 하나의 파이프라인으로 만듭니다.', '`uniq -c` 결과는 맨 앞이 숫자이니, `sort` 에 숫자로 비교하는 옵션(`-n`)과 큰 것부터 보는 옵션(`-r`)을 주면 많은 순이 됩니다. 앞의 몇 줄만 남기는 건 `head -3` 입니다.', 'awk ''{print $1}'' /tmp/lab/access.log | sort | uniq -c | sort -rn | head -3 > /tmp/lab/top3.txt
cat /tmp/lab/top3.txt

# -n 이 없으면 숫자를 글자로 비교해 9 가 12 보다 크다고 본다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab\\ncat > /tmp/lab/access.log <<''LOGEOF''\\n192.0.2.12 - - [10/Nov/2026:09:00:00 +0000] \\"GET /api/login HTTP/1.1\\" 500 198\\n192.0.2.14 - - [10/Nov/2026:09:00:37 +0000] \\"GET /api/orders HTTP/1.1\\" 200 768\\n192.0.2.10 - - [10/Nov/2026:09:01:14 +0000] \\"GET /api/orders HTTP/1.1\\" 200 768\\n192.0.2.12 - - [10/Nov/2026:09:01:51 +0000] \\"GET /index.html HTTP/1.1\\" 200 5120\\n192.0.2.11 - - [10/Nov/2026:09:02:28 +0000] \\"GET /missing.png HTTP/1.1\\" 404 162\\n192.0.2.13 - - [10/Nov/2026:09:03:05 +0000] \\"GET /about.html HTTP/1.1\\" 200 2048\\n192.0.2.11 - - [10/Nov/2026:09:03:42 +0000] \\"GET /api/login HTTP/1.1\\" 200 256\\n192.0.2.12 - - [10/Nov/2026:09:04:19 +0000] \\"GET /about.html HTTP/1.1\\" 200 2048\\n192.0.2.10 - - [10/Nov/2026:09:04:56 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.11 - - [10/Nov/2026:09:05:33 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.10 - - [10/Nov/2026:09:06:10 +0000] \\"GET /api/login HTTP/1.1\\" 200 256\\n192.0.2.12 - - [10/Nov/2026:09:06:47 +0000] \\"GET /about.html HTTP/1.1\\" 200 2048\\n192.0.2.11 - - [10/Nov/2026:09:07:24 +0000] \\"GET /old-page HTTP/1.1\\" 404 162\\n192.0.2.10 - - [10/Nov/2026:09:08:01 +0000] \\"GET /index.html HTTP/1.1\\" 200 5120\\n192.0.2.11 - - [10/Nov/2026:09:08:38 +0000] \\"GET /old-page HTTP/1.1\\" 404 162\\n192.0.2.12 - - [10/Nov/2026:09:09:15 +0000] \\"GET /api/orders HTTP/1.1\\" 200 768\\n192.0.2.12 - - [10/Nov/2026:09:09:52 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.10 - - [10/Nov/2026:09:10:29 +0000] \\"GET /api/orders HTTP/1.1\\" 200 768\\n192.0.2.10 - - [10/Nov/2026:09:11:06 +0000] \\"GET /about.html HTTP/1.1\\" 200 2048\\n192.0.2.10 - - [10/Nov/2026:09:11:43 +0000] \\"GET /api/orders HTTP/1.1\\" 500 321\\n192.0.2.10 - - [10/Nov/2026:09:12:20 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.14 - - [10/Nov/2026:09:12:57 +0000] \\"GET /old-page HTTP/1.1\\" 404 162\\n192.0.2.11 - - [10/Nov/2026:09:13:34 +0000] \\"GET /api/login HTTP/1.1\\" 500 198\\n192.0.2.14 - - [10/Nov/2026:09:14:11 +0000] \\"GET /api/orders HTTP/1.1\\" 200 768\\n192.0.2.11 - - [10/Nov/2026:09:14:48 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.13 - - [10/Nov/2026:09:15:25 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.13 - - [10/Nov/2026:09:16:02 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.10 - - [10/Nov/2026:09:16:39 +0000] \\"GET /api/orders HTTP/1.1\\" 500 321\\n192.0.2.11 - - [10/Nov/2026:09:17:16 +0000] \\"GET /api/login HTTP/1.1\\" 500 198\\n192.0.2.10 - - [10/Nov/2026:09:17:53 +0000] \\"GET /index.html HTTP/1.1\\" 200 5120\\n192.0.2.12 - - [10/Nov/2026:09:18:30 +0000] \\"GET /static/app.js HTTP/1.1\\" 200 40960\\n192.0.2.11 - - [10/Nov/2026:09:19:07 +0000] \\"GET /missing.png HTTP/1.1\\" 404 162\\n192.0.2.10 - - [10/Nov/2026:09:19:44 +0000] \\"GET /about.html HTTP/1.1\\" 200 2048\\n192.0.2.10 - - [10/Nov/2026:09:20:21 +0000] \\"GET /about.html HTTP/1.1\\" 200 2048\\n192.0.2.10 - - [10/Nov/2026:09:20:58 +0000] \\"GET /api/login HTTP/1.1\\" 500 198\\n192.0.2.14 - - [10/Nov/2026:09:21:35 +0000] \\"GET /old-page HTTP/1.1\\" 404 162\\nLOGEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/lab/top3.txt)\\" -eq 3 ] ) && ( [ \\"$(awk ''{print $2\\" \\"$1}'' /tmp/lab/top3.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"097cfac6d6ba3ce68856e352a802e897\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "세 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/top3.txt)\\" -eq 3 ]"]}, {"label": "상위 3개 IP 가 많은 순으로 정확하다", "cmd": ["sh", "-c", "[ \\"$(awk ''{print $2\\" \\"$1}'' /tmp/lab/top3.txt | md5sum | cut -d\\" \\" -f1)\\" = \\"097cfac6d6ba3ce68856e352a802e897\\" ]"]}]', '[{"title": "GNU coreutils 매뉴얼: sort 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/sort-invocation.html"}, {"title": "GNU coreutils 매뉴얼: uniq 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/uniq-invocation.html"}, {"title": "GNU coreutils 매뉴얼: cut 사용법", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cut-invocation.html"}, {"title": "GNU awk 사용자 안내서: 필드 읽기", "url": "https://www.gnu.org/software/gawk/manual/html_node/Fields.html"}]'
